(function(){'use strict';const AUTH=/^#\/(login|signin|register|forgot-password|verify-email|reset-password|login-2fa)/;let booted=false;async function boot(){if(booted||AUTH.test(location.hash))return;const root=document.getElementById('vexa-react-root')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'vexa-react-root'}));try{const base=window.VEXA_ACCOUNT_API_BASE||'https://api-vexaaccount.onrender.com';const token=window.vexaAccountAuth?.getToken?.();const r=await fetch(base+'/api/auth/session',{credentials:'include',headers:token?{Authorization:'Bearer '+token}:{}});const d=await r.json().catch(()=>({success:false,message:'No session'}));if(!r.ok||d.success!==true||!d.user){if(!token){location.hash='#/login';return}return}booted=true;const old=document.getElementById('app');if(old)old.style.display='none';root.style.display='block';['./src/react-account-center.css','./src/hooks/useNotification.js','./src/components/ToastNotification.js','./src/react-account-center.js'].forEach(src=>{if(src.endsWith('.css')){const l=document.createElement('link');l.rel='stylesheet';l.href=src+'?v=20260902-8';document.head.appendChild(l)}else{const s=document.createElement('script');s.src=src+'?v=20260902-8';s.defer=false;document.body.appendChild(s)}})}catch(e){console.warn('VexaAccount React Account Center boot skipped:',e.message)}}window.addEventListener('hashchange',boot);setTimeout(boot,900);})();
